@page "/recipes"
@page "/recipes/{CategoryFilter}"

<PageTitle>Browse Recipes</PageTitle>

<h1>📖 Browse Recipes</h1>

@if (!string.IsNullOrEmpty(CategoryFilter))
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Recipes</a></li>
            <li class="breadcrumb-item active">@CategoryFilter</li>
        </ol>
    </nav>
}

<div class="row mt-3">
    @foreach (var recipe in FilteredRecipes)
    {
        <div class="col-md-6 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary">@recipe.Category</span>
                    <p class="mt-2 text-muted">
                        ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                    </p>
                    <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!FilteredRecipes.Any())
{
    <p class="text-muted">No recipes found in this category.</p>
}

@code {
    [Parameter]
    public string? CategoryFilter { get; set; }

    private IEnumerable<RecipeCommunity.Models.Recipe> FilteredRecipes =>
        string.IsNullOrEmpty(CategoryFilter)
            ? RecipeCommunity.Models.RecipeData.Recipes
            : RecipeCommunity.Models.RecipeData.Recipes
                .Where(r => r.Category.Equals(CategoryFilter, StringComparison.OrdinalIgnoreCase));
}

@page "/recipe/{Id:int}"

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Recipes</a></li>
            <li class="breadcrumb-item"><a href="@($"recipes/{recipe.Category.ToLower()}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="list-unstyled">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Instructions</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this Recipe</h4>
        <p class="text-muted">Current rating: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
        <RecipeCommunity.Components.Shared.StarRating RecipeId="recipe.Id" />
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeCommunity.Models.RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              style="cursor:pointer; font-size:1.8rem;"
              title="@star star(s)">
            @(star <= selectedRating ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks! You rated @selectedRating star(s).</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating = 0;
    private bool submitted = false;

    private void Rate(int rating)
    {
        selectedRating = rating;
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@model.Title</strong>" with the community.</p>
        <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" class="mt-4">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeCommunity.Models.RecipeData.Categories)
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" placeholder="One ingredient per line" />
            <ValidationMessage For="() => model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps" placeholder="Describe the steps to make this recipe" />
            <ValidationMessage For="() => model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private bool isSubmitted = false;

    private void HandleSubmit()
    {
        isSubmitted = true;
    }

    private void Reset()
    {
        model = new();
        isSubmitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

